import React, { useEffect, useState } from 'react';
import QRCode from 'qrcode';

interface VectorQRCodeProps {
  /** JSON string generated by stringifyQrPayload. */
  dataString: string;
  isEmergency?: boolean;
  size?: number;
}

export const VectorQRCode: React.FC<VectorQRCodeProps> = ({
  dataString,
  isEmergency = false,
  size = 220,
}) => {
  const [svgContent, setSvgContent] = useState<string>('');
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    let isMounted = true;

    try {
      const parsed: unknown = JSON.parse(dataString);
      if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed)) {
        throw new TypeError('El contenido debe ser un objeto JSON.');
      }
    } catch {
      setError('El contenido del QR no es un JSON válido.');
      setSvgContent('');
      return () => {
        isMounted = false;
      };
    }

    // Render plain JSON as text, with a white quiet zone for reliable camera scanning.
    QRCode.toString(dataString, {
      type: 'svg',
      errorCorrectionLevel: 'M',
      margin: 2,
      width: size,
      color: {
        dark: isEmergency ? '#b91c1c' : '#0f172a',
        light: '#ffffff',
      },
    })
      .then((svg) => {
        if (isMounted) {
          setSvgContent(svg.replace(/<svg /, '<svg role="img" aria-label="Código QR del triaje" '));
          setError(null);
        }
      })
      .catch((err) => {
        if (isMounted) {
          console.error('Error generating vector QR code:', err);
          setError('Error al generar QR');
        }
      });

    return () => {
      isMounted = false;
    };
  }, [dataString, isEmergency, size]);

  const downloadQr = () => {
    if (!svgContent) return;
    const blob = new Blob([svgContent], { type: 'image/svg+xml;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'triaje-qr.svg';
    link.click();
    window.setTimeout(() => URL.revokeObjectURL(url), 1000);
  };

  if (error) {
    return (
      <div className="w-full h-full flex flex-col items-center justify-center text-xs text-red-500 font-mono p-2 text-center">
        <i className="fa-solid fa-triangle-exclamation text-base mb-1"></i>
        <span>{error}</span>
      </div>
    );
  }

  if (!svgContent) {
    return (
      <div className="w-full h-full flex items-center justify-center">
        <i className="fa-solid fa-circle-notch animate-spin text-slate-400 text-lg"></i>
      </div>
    );
  }

  return (
    <div className="flex h-full w-full flex-col items-center justify-center gap-1">
      <div
        className="flex min-h-0 w-full flex-1 items-center justify-center select-none [&>svg]:h-full [&>svg]:max-h-full [&>svg]:max-w-full [&>svg]:w-full"
        dangerouslySetInnerHTML={{ __html: svgContent }}
      />
      <button
        type="button"
        onClick={downloadQr}
        aria-label="Descargar código QR"
        className="shrink-0 rounded-full px-2 py-1 text-[10px] font-bold text-slate-600 hover:bg-slate-100 focus-visible:outline focus-visible:outline-2 focus-visible:outline-blue-600"
      >
        <i className="fa-solid fa-download mr-1" aria-hidden="true" />Descargar QR
      </button>
    </div>
  );
};
